private int counter = 0;      
       decimal shuma_agjent = 0;
        String agjenti = "";
private void xrLabel27_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
   counter++;
            xrLabel27.Text = counter.ToString();
}

private void xrLabel21_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {

            if (agjenti != "")
            {
                if (GetCurrentColumnValue("KODAGJENT1") != null)
                    if (GetCurrentColumnValue("KODAGJENT1").ToString() == agjenti) shuma_agjent += Convert.ToDecimal(GetCurrentColumnValue("PERQINDJEAGJENTI1").ToString()) * Convert.ToDecimal(GetCurrentColumnValue("VLEFTAPATVSH").ToString()) * Convert.ToDecimal(0.01);

                if ((GetCurrentColumnValue("KODAGJENT2") != null))
                    if (GetCurrentColumnValue("KODAGJENT2").ToString() == agjenti) shuma_agjent += Convert.ToDecimal(GetCurrentColumnValue("PERQINDJEAGJENTI2").ToString()) * Convert.ToDecimal(GetCurrentColumnValue("VLEFTAPATVSH").ToString()) * Convert.ToDecimal(0.01);

                if ((GetCurrentColumnValue("KODAGJENT3") != null))
                    if (GetCurrentColumnValue("KODAGJENT3").ToString() == agjenti) shuma_agjent += Convert.ToDecimal(GetCurrentColumnValue("PERQINDJEAGJENTI3").ToString()) * Convert.ToDecimal(GetCurrentColumnValue("VLEFTAPATVSH").ToString()) * Convert.ToDecimal(0.01);
            }
}
private void xrLabel16_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
 double paguar;
            bool konv = double.TryParse(xrLabel16.Text, out paguar);
            if (konv)
                xrLabel16.Text = String.Format("{0:#.00}", paguar);
}

private void xrLabel35_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
   xrLabel35.Text = String.Format("{0:#,#.00}", shuma_agjent);
}
private void filtraTable_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
AlphaWebReports.raporteUtil.shtoFiltra(filtraTable, kokaTable, AlphaWebReports.raporteUtil.DeserializoParametrat(this.Extensions["filtrat"]));
}
